from jsonb_to_recordset($q$[{"id":7639,"materia":"pen","nivel":0,"enunciado":"Jéssica pega emprestada a bicicleta da amiga e depois a vende como se fosse sua. Ela comete:","opcoes":["Apropriação indébita","Furto","Roubo","Receptação"],"explicacao":"Tinha a posse lícita e passou a agir como dona: art. 168 do CP."},{"id":7640,"materia":"pen","nivel":0,"enunciado":"Um homem invade a casa do vizinho, sem levar nada, apenas para assustá-lo. Ele comete:","opcoes":["Violação de domicílio","Furto","Dano","Roubo"],"explicacao":"Art. 150 do CP."},{"id":7641,"materia":"pen","nivel":0,"enunciado":"Quem dirige o carro de outra pessoa sem permissão, para dar uma volta e devolvê-lo intacto, pratica, segundo a doutrina:","opcoes":["Furto de uso, fato atípico em regra","Roubo","Furto qualificado","Receptação"],"explicacao":"O furto de uso não é crime no CP, desde que a coisa seja devolvida logo e intacta."},{"id":7642,"materia":"pen","nivel":0,"enunciado":"O servidor público que recebe propina para liberar um documento comete:","opcoes":["Corrupção passiva","Corrupção ativa","Concussão","Peculato"],"explicacao":"Receber vantagem indevida em razão da função: art. 317."},{"id":7643,"materia":"pen","nivel":0,"enunciado":"Fugir de uma blitz após ordem legal de parada do policial, sem violência, pode configurar:","opcoes":["Desobediência","Desacato","Resistência","Corrupção ativa"],"explicacao":"Art. 330 do CP."},{"id":7644,"materia":"pen","nivel":0,"enunciado":"Empurrar e agredir o policial que tenta prender alguém legalmente é crime de:","opcoes":["Resistência","Desobediência","Desacato","Ameaça"],"explicacao":"Oposição à execução de ato legal com violência ou ameaça: art. 329."},{"id":7645,"materia":"pen","nivel":0,"enunciado":"Quem dá fuga a preso que está sob sua guarda, como carcereiro, comete:","opcoes":["Facilitação de fuga de pessoa presa","Favorecimento real","Prevaricação","Evasão mediante violência"],"explicacao":"Art. 351 do CP, com pena maior para o funcionário encarregado."},{"id":7646,"materia":"pen","nivel":0,"enunciado":"Fazer registro de ocorrência falso, comunicando um crime que não aconteceu, é:","opcoes":["Comunicação falsa de crime","Denunciação caluniosa","Calúnia","Falso testemunho"],"explicacao":"Art. 340 do CP. Se imputar a pessoa determinada, é denunciação caluniosa."},{"id":7647,"materia":"pen","nivel":0,"enunciado":"Alterar a cena de um crime para enganar a perícia é:","opcoes":["Fraude processual","Favorecimento real","Dano","Desobediência"],"explicacao":"Art. 347 do CP."},{"id":7648,"materia":"pen","nivel":0,"enunciado":"Fazer uma carteira de motorista falsa é crime de:","opcoes":["Falsificação de documento público","Falsidade ideológica","Estelionato","Uso de documento falso, apenas"],"explicacao":"Art. 297 do CP. Usar o documento é o crime do art. 304."},{"id":7649,"materia":"pen","nivel":1,"enunciado":"Inserir informação falsa em documento verdadeiro, como declarar renda falsa numa ficha oficial, é:","opcoes":["Falsidade ideológica","Falsificação de documento público","Uso de documento falso","Estelionato"],"explicacao":"Art. 299 do CP: o documento é materialmente verdadeiro, mas a ideia é falsa."},{"id":7650,"materia":"pen","nivel":1,"enunciado":"Imputar falsamente crime a alguém, dando causa à instauração de inquérito contra ele, é:","opcoes":["Denunciação caluniosa","Calúnia","Comunicação falsa de crime","Difamação"],"explicacao":"Art. 339 do CP."},{"id":7651,"materia":"pen","nivel":1,"enunciado":"A participação de menor importância permite:","opcoes":["Reduzir a pena de 1/6 a 1/3","Isentar de pena","Aumentar a pena","Converter em multa obrigatoriamente"],"explicacao":"Art. 29, § 1º, do CP."},{"id":7652,"materia":"pen","nivel":1,"enunciado":"O crime de omissão de socorro tem a pena aumentada se:","opcoes":["Da omissão resulta lesão grave ou morte","A vítima for maior de idade","O fato ocorrer de dia","O omitente for estrangeiro"],"explicacao":"Art. 135, parágrafo único: metade (lesão grave) ou triplicada (morte)."},{"id":7653,"materia":"pen","nivel":1,"enunciado":"A extorsão mediante sequestro é crime:","opcoes":["Hediondo","De menor potencial ofensivo","Culposo","Afiançável pelo delegado"],"explicacao":"Lei 8.072/1990, art. 1º, IV."},{"id":7654,"materia":"pen","nivel":1,"enunciado":"O furto de coisa comum, entre sócios ou herdeiros, procede-se mediante:","opcoes":["Representação","Queixa","Ação pública incondicionada","Requisição do Ministro da Justiça"],"explicacao":"Art. 156, § 1º, do CP."},{"id":7655,"materia":"pen","nivel":2,"enunciado":"Matar alguém por motivo fútil, como uma discussão por lugar na fila, caracteriza homicídio:","opcoes":["Qualificado","Privilegiado","Simples","Culposo"],"explicacao":"Art. 121, § 2º, II, do CP."},{"id":7656,"materia":"pen","nivel":2,"enunciado":"Matar sob o domínio de violenta emoção, logo em seguida a injusta provocação da vítima, caracteriza homicídio:","opcoes":["Privilegiado, com redução de 1/6 a 1/3","Qualificado","Culposo","Simples sem redução"],"explicacao":"Art. 121, § 1º, do CP."},{"id":7657,"materia":"pen","nivel":2,"enunciado":"O furto qualificado pelo concurso de duas ou mais pessoas tem pena de:","opcoes":["Reclusão de 2 a 8 anos","Reclusão de 1 a 4 anos","Reclusão de 3 a 10 anos","Detenção de 1 a 2 anos"],"explicacao":"Art. 155, § 4º, IV, do CP."},{"id":7658,"materia":"pen","nivel":2,"enunciado":"A extorsão praticada com restrição da liberdade da vítima, quando essa condição é necessária para obter a vantagem, é o chamado:","opcoes":["Sequestro relâmpago","Roubo impróprio","Extorsão indireta","Furto mediante fraude"],"explicacao":"Art. 158, § 3º, do CP."},{"id":7659,"materia":"pen","nivel":2,"enunciado":"O agente que comete o crime em erro inevitável sobre a ilicitude do fato:","opcoes":["É isento de pena","Responde normalmente","Tem a pena aumentada","Responde por crime culposo"],"explicacao":"Erro de proibição inevitável: art. 21 do CP. Se evitável, reduz de 1/6 a 1/3."},{"id":7660,"materia":"pen","nivel":3,"enunciado":"O homicídio culposo tem pena aumentada de 1/3 se o agente:","opcoes":["Deixa de prestar imediato socorro à vítima","É primário","Confessa espontaneamente","Tem menos de 21 anos"],"explicacao":"Art. 121, § 4º, do CP."},{"id":7661,"materia":"pen","nivel":3,"enunciado":"No homicídio culposo, o juiz pode deixar de aplicar a pena quando:","opcoes":["As consequências da infração atingem o próprio agente de forma tão grave que a sanção se torna desnecessária","O agente é rico","A vítima era desconhecida","O agente confessa"],"explicacao":"Perdão judicial: art. 121, § 5º, do CP."},{"id":7662,"materia":"pen","nivel":3,"enunciado":"O furto de pequeno valor por criminoso primário pode ter, entre outras consequências:","opcoes":["Substituição da reclusão por detenção, redução de 1/3 a 2/3 ou só multa","Absolvição obrigatória","Aumento de pena","Conversão em crime hediondo"],"explicacao":"Furto privilegiado: art. 155, § 2º, do CP."},{"id":7663,"materia":"pen","nivel":3,"enunciado":"O STJ considera “pequeno valor”, para o furto privilegiado, a coisa que vale até:","opcoes":["1 salário mínimo","R$ 100,00","Meio salário mínimo","5 salários mínimos"],"explicacao":"Jurisprudência consolidada do STJ."},{"id":7664,"materia":"pen","nivel":3,"enunciado":"Para aplicar o princípio da insignificância, o STF exige, entre outros requisitos:","opcoes":["Mínima ofensividade, ausência de periculosidade social, reduzido grau de reprovabilidade e inexpressividade da lesão","Apenas o pequeno valor","Que o réu seja rico","Que a vítima perdoe"],"explicacao":"Vetores fixados no HC 84.412."},{"id":7665,"materia":"pen","nivel":3,"enunciado":"O roubo praticado com emprego de arma branca tem a pena:","opcoes":["Aumentada de 1/3 até a metade","Aplicada em dobro","Aumentada de 2/3","Igual à do roubo simples"],"explicacao":"Art. 157, § 2º, VII, do CP (Lei 13.964/2019)."},{"id":7666,"materia":"pen","nivel":3,"enunciado":"O roubo praticado com emprego de arma de fogo de uso permitido tem a pena:","opcoes":["Aumentada de 2/3","Aplicada em dobro","Aumentada de 1/3","Aumentada da metade"],"explicacao":"Art. 157, § 2º-A, I, do CP."},{"id":7667,"materia":"pen","nivel":3,"enunciado":"A medida de segurança é aplicada ao:","opcoes":["Inimputável que pratica fato típico e ilícito","Réu primário","Réu reincidente","Menor de 18 anos"],"explicacao":"Arts. 96 e 97 do CP. O semi-imputável pode ter pena reduzida ou medida de segurança."},{"id":7668,"materia":"pen","nivel":4,"enunciado":"No crime continuado específico, contra vítimas diferentes, com violência ou grave ameaça, o juiz pode aumentar a pena:","opcoes":["Até o triplo","Até o dobro","De 1/6 a 2/3 apenas","De 1/3 até a metade"],"explicacao":"Art. 71, parágrafo único, do CP."},{"id":7669,"materia":"pen","nivel":4,"enunciado":"O limite máximo de cumprimento das penas privativas de liberdade, após o Pacote Anticrime, é de:","opcoes":["40 anos","30 anos","50 anos","35 anos"],"explicacao":"Art. 75 do CP, com a Lei 13.964/2019."},{"id":7670,"materia":"pen","nivel":4,"enunciado":"Sobrevindo condenação por fato posterior ao início do cumprimento da pena, o limite de 40 anos:","opcoes":["É recalculado, desprezando-se o período de pena já cumprido","Deixa de existir","Dobra automaticamente","É mantido sem alteração"],"explicacao":"Art. 75, § 2º, do CP."},{"id":7671,"materia":"pen","nivel":4,"enunciado":"A prescrição da pretensão executória, depois de transitar em julgado a sentença, regula-se:","opcoes":["Pela pena aplicada, aumentada de 1/3 se o condenado for reincidente","Pelo máximo da pena cominada","Pela pena mínima prevista","Pelo dobro da pena aplicada"],"explicacao":"Art. 110, caput, do CP."},{"id":7672,"materia":"pen","nivel":4,"enunciado":"A prescrição retroativa, calculada pela pena aplicada, não pode ter como termo inicial data anterior à:","opcoes":["Denúncia ou queixa","Data do fato","Sentença","Prisão do réu"],"explicacao":"Art. 110, § 1º, do CP (Lei 12.234/2010)."},{"id":7673,"materia":"pen","nivel":4,"enunciado":"No crime de peculato, o funcionário que se apropria de bem particular que está sob a guarda da administração:","opcoes":["Comete peculato, pois o tipo abrange bem particular sob a posse do funcionário em razão do cargo","Comete apenas furto","Não comete crime","Comete apropriação indébita comum"],"explicacao":"Art. 312 do CP: dinheiro, valor ou bem móvel, público ou particular."},{"id":7674,"materia":"pen","nivel":4,"enunciado":"O crime de concussão se consuma:","opcoes":["Com a simples exigência da vantagem indevida","Somente com o recebimento da vantagem","Com a denúncia do particular","Com a prisão do servidor"],"explicacao":"Crime formal: o recebimento é exaurimento."},{"id":7675,"materia":"pen","nivel":4,"enunciado":"A pena do estupro de vulnerável é de:","opcoes":["Reclusão de 8 a 15 anos","Reclusão de 6 a 10 anos","Reclusão de 12 a 30 anos","Detenção de 2 a 4 anos"],"explicacao":"Art. 217-A do CP."},{"id":7676,"materia":"pen","nivel":4,"enunciado":"Para o STJ, o crime de roubo se consuma:","opcoes":["Com a inversão da posse do bem, mediante violência ou grave ameaça, ainda que por breve tempo e com perseguição imediata","Somente com a posse mansa e pacífica do bem","Somente se o agente fugir para longe","Apenas com a venda do bem"],"explicacao":"Súmula 582 do STJ (teoria da amotio)."},{"id":7677,"materia":"pen","nivel":4,"enunciado":"A pena-base é fixada pelo juiz considerando:","opcoes":["As circunstâncias judiciais do art. 59 (culpabilidade, antecedentes, conduta social, personalidade, motivos, circunstâncias, consequências e comportamento da vítima)","Apenas os antecedentes","Somente a confissão","O pedido da acusação"],"explicacao":"Primeira fase da dosimetria (sistema trifásico do art. 68)."},{"id":7678,"materia":"pen","nivel":4,"enunciado":"Na segunda fase da dosimetria, a pena intermediária, segundo a Súmula 231 do STJ:","opcoes":["Não pode ser reduzida abaixo do mínimo legal por atenuantes","Pode ficar abaixo do mínimo","Pode passar do máximo por agravantes","Não sofre influência de agravantes"],"explicacao":"Súmula 231 do STJ."},{"id":7679,"materia":"pen","nivel":4,"enunciado":"A circunstância agravante da reincidência e a atenuante da confissão espontânea, segundo o STJ, em regra:","opcoes":["Compensam-se","Não se compensam nunca","Somam-se para aumentar a pena","Excluem a pena"],"explicacao":"STJ, Tema 585, salvo multirreincidência."},{"id":7680,"materia":"pen","nivel":4,"enunciado":"Para fins penais, o funcionário público por equiparação inclui quem trabalha:","opcoes":["Em empresa prestadora de serviço contratada ou conveniada para executar atividade típica da administração","Em qualquer empresa privada","Apenas como voluntário em ONGs","Somente em cargo eletivo"],"explicacao":"Art. 327, § 1º, do CP."},{"id":7681,"materia":"leg","nivel":0,"enunciado":"Carla é agredida pelo ex-namorado, com quem não mora mais. A Lei Maria da Penha:","opcoes":["Se aplica, pois abrange relação íntima de afeto, independentemente de coabitação","Não se aplica, pois não moram juntos","Só se aplica se forem casados","Só se aplica se houver filhos"],"explicacao":"Art. 5º, III, da Lei 11.340/2006 e Súmula 600 do STJ."},{"id":7682,"materia":"leg","nivel":0,"enunciado":"Pelo ECA, adolescente que pratica ato infracional pode receber:","opcoes":["Medida socioeducativa","Pena de prisão comum","Multa criminal","Pena de morte"],"explicacao":"Art. 112 do ECA."},{"id":7683,"materia":"leg","nivel":0,"enunciado":"Vender bebida alcoólica para menor de 18 anos é:","opcoes":["Crime","Mera infração administrativa","Permitido se os pais deixarem","Contravenção revogada"],"explicacao":"Art. 243 do ECA."},{"id":7684,"materia":"leg","nivel":0,"enunciado":"Pela Lei de Drogas, cultivar pequena quantidade de planta para consumo pessoal recebe o mesmo tratamento:","opcoes":["Do porte para consumo pessoal","Do tráfico","Da associação para o tráfico","Do financiamento do tráfico"],"explicacao":"Art. 28, § 1º, da Lei 11.343/2006."},{"id":7685,"materia":"leg","nivel":0,"enunciado":"Qual lei define os crimes hediondos?","opcoes":["Lei 8.072/1990","Lei 9.455/1997","Lei 10.826/2003","Lei 12.850/2013"],"explicacao":""},{"id":7686,"materia":"leg","nivel":0,"enunciado":"Dirigir sem habilitação gerando perigo de dano é:","opcoes":["Crime de trânsito","Apenas multa, sem crime","Contravenção","Fato atípico"],"explicacao":"Art. 309 do CTB."},{"id":7687,"materia":"leg","nivel":0,"enunciado":"Participar de “racha” em via pública, gerando situação de risco, é:","opcoes":["Crime de trânsito","Infração leve","Fato atípico","Contravenção"],"explicacao":"Art. 308 do CTB."},{"id":7688,"materia":"leg","nivel":0,"enunciado":"O Estatuto da Pessoa Idosa considera idosa a pessoa com idade igual ou superior a:","opcoes":["60 anos","65 anos","70 anos","55 anos"],"explicacao":"Art. 1º da Lei 10.741/2003."},{"id":7689,"materia":"leg","nivel":0,"enunciado":"Pela Lei Maria da Penha, o agressor pode ser obrigado a:","opcoes":["Afastar-se do lar e manter distância da vítima","Pagar multa de trânsito","Mudar de nome","Trocar de emprego"],"explicacao":"Art. 22 da Lei 11.340/2006."},{"id":7690,"materia":"leg","nivel":1,"enunciado":"Pela Lei de Drogas, associarem-se duas ou mais pessoas para praticar tráfico é crime de:","opcoes":["Associação para o tráfico","Organização criminosa","Associação criminosa do CP","Tráfico privilegiado"],"explicacao":"Art. 35 da Lei 11.343/2006: basta 2 pessoas."},{"id":7691,"materia":"leg","nivel":1,"enunciado":"A Lei 13.104/2015 incluiu no Código Penal o:","opcoes":["Feminicídio, que hoje é crime autônomo","Furto de celular","Crime de stalking","Racismo religioso"],"explicacao":"Era qualificadora; a Lei 14.994/2024 o transformou em crime autônomo."},{"id":7692,"materia":"leg","nivel":1,"enunciado":"Perseguir alguém reiteradamente, ameaçando sua integridade ou invadindo sua privacidade, é o crime de:","opcoes":["Perseguição (stalking)","Ameaça simples","Constrangimento ilegal","Violação de domicílio"],"explicacao":"Art. 147-A do CP (Lei 14.132/2021)."},{"id":7693,"materia":"leg","nivel":1,"enunciado":"Causar dano emocional à mulher que a prejudique e perturbe seu pleno desenvolvimento é crime de:","opcoes":["Violência psicológica contra a mulher","Injúria","Ameaça","Lesão corporal leve"],"explicacao":"Art. 147-B do CP (Lei 14.188/2021)."},{"id":7694,"materia":"leg","nivel":1,"enunciado":"Pelo ECA, a remissão pode ser concedida pelo Ministério Público:","opcoes":["Antes de iniciado o procedimento judicial, como forma de exclusão do processo","Somente após a sentença","Apenas pelo delegado","Nunca"],"explicacao":"Art. 126 do ECA."},{"id":7695,"materia":"leg","nivel":2,"enunciado":"Pelo CTB, a lesão corporal culposa na direção de veículo tem pena de:","opcoes":["Detenção de 6 meses a 2 anos e suspensão ou proibição de dirigir","Reclusão de 2 a 5 anos","Detenção de 2 a 4 anos","Apenas multa"],"explicacao":"Art. 303 do CTB."},{"id":7696,"materia":"leg","nivel":2,"enunciado":"Pela Lei Maria da Penha, nos crimes de violência doméstica contra a mulher, é vedada a aplicação de pena de:","opcoes":["Cesta básica ou outras de prestação pecuniária, e a substituição por multa isolada","Prisão","Reclusão","Detenção"],"explicacao":"Art. 17 da Lei 11.340/2006."},{"id":7697,"materia":"leg","nivel":2,"enunciado":"O Estatuto do Desarmamento considera crime omitir as cautelas necessárias para impedir que menor de 18 anos se apodere de arma de fogo. Esse crime é a:","opcoes":["Omissão de cautela","Posse irregular","Porte ilegal","Disparo de arma"],"explicacao":"Art. 13 da Lei 10.826/2003."},{"id":7698,"materia":"leg","nivel":2,"enunciado":"Pela Lei de Execução Penal, a remição por trabalho é de:","opcoes":["1 dia de pena a cada 3 dias de trabalho","1 dia a cada 2 dias de trabalho","1 dia a cada 5 dias de trabalho","2 dias a cada 3 dias de trabalho"],"explicacao":"Art. 126, § 1º, II, da LEP."},{"id":7699,"materia":"leg","nivel":2,"enunciado":"Pela LEP, a remição por estudo é de:","opcoes":["1 dia de pena a cada 12 horas de frequência escolar, divididas em no mínimo 3 dias","1 dia a cada 6 horas de estudo","1 dia a cada 24 horas","2 dias por semana de aula"],"explicacao":"Art. 126, § 1º, I, da LEP."},{"id":7700,"materia":"leg","nivel":2,"enunciado":"Pela LEP, a falta grave praticada pelo preso pode levar à:","opcoes":["Regressão de regime e perda de até 1/3 dos dias remidos","Extinção da pena","Progressão automática","Soltura imediata"],"explicacao":"Arts. 118 e 127 da LEP."},{"id":7701,"materia":"leg","nivel":3,"enunciado":"O regime disciplinar diferenciado (RDD), após a Lei 13.964/2019, tem duração máxima de:","opcoes":["2 anos, sem prejuízo de repetição por nova falta grave","360 dias","1 ano, improrrogável","6 meses"],"explicacao":"Art. 52, I, da LEP."},{"id":7702,"materia":"leg","nivel":3,"enunciado":"Pelo Estatuto do Desarmamento, o comércio ilegal de arma de fogo tem pena de:","opcoes":["Reclusão de 6 a 12 anos e multa","Reclusão de 2 a 4 anos","Reclusão de 3 a 6 anos","Detenção de 1 a 3 anos"],"explicacao":"Art. 17 da Lei 10.826/2003 (Lei 13.964/2019)."},{"id":7703,"materia":"leg","nivel":3,"enunciado":"O tráfico internacional de arma de fogo tem pena de:","opcoes":["Reclusão de 8 a 16 anos e multa","Reclusão de 4 a 8 anos","Reclusão de 6 a 12 anos","Reclusão de 2 a 6 anos"],"explicacao":"Art. 18 da Lei 10.826/2003."},{"id":7704,"materia":"leg","nivel":3,"enunciado":"Pela Lei de Organizações Criminosas, quem integra organização criminosa tem pena de:","opcoes":["Reclusão de 3 a 8 anos e multa","Reclusão de 1 a 3 anos","Reclusão de 5 a 15 anos","Detenção de 2 a 4 anos"],"explicacao":"Art. 2º da Lei 12.850/2013."},{"id":7705,"materia":"leg","nivel":3,"enunciado":"A pena da organização criminosa é aumentada até a metade se:","opcoes":["Houver emprego de arma de fogo","O réu for primário","A organização tiver 4 membros","O crime for culposo"],"explicacao":"Art. 2º, § 2º, da Lei 12.850/2013."},{"id":7706,"materia":"leg","nivel":3,"enunciado":"Pelo ECA, a internação do adolescente só pode ser aplicada quando:","opcoes":["O ato infracional for cometido com grave ameaça ou violência, houver reiteração de infrações graves ou descumprimento reiterado de medida anterior","O adolescente tiver mais de 16 anos","Houver qualquer ato infracional","Os pais pedirem"],"explicacao":"Art. 122 do ECA."},{"id":7707,"materia":"leg","nivel":3,"enunciado":"Pelo ECA, a medida de internação por descumprimento reiterado e injustificável de medida anterior não pode exceder:","opcoes":["3 meses","45 dias","6 meses","1 ano"],"explicacao":"Art. 122, § 1º, do ECA."},{"id":7708,"materia":"leg","nivel":3,"enunciado":"Para o STJ, a Lei Maria da Penha se aplica às mulheres trans?","opcoes":["Sim","Não","Só com cirurgia","Só se tiverem mudado o registro civil"],"explicacao":"STJ, REsp 1.977.124 (2022)."},{"id":7709,"materia":"leg","nivel":3,"enunciado":"Pela Lei de Abuso de Autoridade, é crime constranger o preso, mediante violência ou grave ameaça, a:","opcoes":["Exibir-se à curiosidade pública ou submeter-se a situação vexatória","Assinar o termo de prisão","Fornecer endereço","Comparecer à audiência"],"explicacao":"Art. 13 da Lei 13.869/2019."},{"id":7710,"materia":"leg","nivel":4,"enunciado":"Pela Lei de Drogas, a pena do tráfico é aumentada de 1/6 a 2/3 quando:","opcoes":["A infração for praticada nas imediações de escolas, hospitais ou unidades policiais, entre outras hipóteses","O agente for primário","A droga for maconha","O agente confessar"],"explicacao":"Art. 40, III, da Lei 11.343/2006."},{"id":7711,"materia":"leg","nivel":4,"enunciado":"Pela Súmula 587 do STJ, para a majorante do tráfico entre estados:","opcoes":["É desnecessária a efetiva transposição da fronteira, bastando a prova da destinação","É preciso a efetiva entrada da droga no outro estado","Exige prisão na fronteira","Só vale para cocaína"],"explicacao":"Súmula 587 do STJ."},{"id":7712,"materia":"leg","nivel":4,"enunciado":"Na Lei de Organizações Criminosas, o prazo para a conclusão da instrução criminal com réu preso é de até:","opcoes":["120 dias, prorrogáveis por igual período","60 dias","90 dias, improrrogáveis","180 dias"],"explicacao":"Art. 22, parágrafo único, da Lei 12.850/2013."},{"id":7713,"materia":"leg","nivel":4,"enunciado":"Pela Lei Maria da Penha, o juiz pode determinar ao agressor o comparecimento a programas de recuperação e reeducação e o:","opcoes":["Acompanhamento psicossocial, por atendimento individual ou em grupo","Pagamento de fiança à vítima","Alistamento militar","Exame de DNA obrigatório"],"explicacao":"Art. 22, VI e VII, da Lei 11.340/2006 (Lei 13.984/2020)."},{"id":7714,"materia":"leg","nivel":4,"enunciado":"Pela LEP, a progressão do primário em crime sem violência ou grave ameaça exige o cumprimento de:","opcoes":["16% da pena","25% da pena","20% da pena","1/6 da pena"],"explicacao":"Art. 112, I, da LEP."},{"id":7715,"materia":"leg","nivel":4,"enunciado":"Pela LEP, a progressão do primário em crime cometido com violência ou grave ameaça exige:","opcoes":["25% da pena","16% da pena","30% da pena","40% da pena"],"explicacao":"Art. 112, III, da LEP."},{"id":7716,"materia":"leg","nivel":4,"enunciado":"Pela LEP, a progressão do reincidente em crime hediondo ou equiparado, sem resultado morte, exige:","opcoes":["60% da pena","50% da pena","40% da pena","70% da pena"],"explicacao":"Art. 112, VII, da LEP."},{"id":7717,"materia":"leg","nivel":4,"enunciado":"Na lavagem de dinheiro, a colaboração espontânea do autor pode levar a:","opcoes":["Redução de 1/3 a 2/3, regime aberto ou semiaberto, ou perdão judicial","Aumento de pena","Prisão perpétua","Perda do direito de defesa"],"explicacao":"Art. 1º, § 5º, da Lei 9.613/1998."},{"id":7718,"materia":"leg","nivel":4,"enunciado":"Pelo CTB, praticar lesão corporal culposa grave ou gravíssima sob a influência de álcool tem pena de:","opcoes":["Reclusão de 2 a 5 anos","Detenção de 6 meses a 2 anos","Reclusão de 5 a 8 anos","Detenção de 1 a 3 anos"],"explicacao":"Art. 303, § 2º, do CTB."},{"id":7719,"materia":"leg","nivel":4,"enunciado":"O tráfico de pessoas (art. 149-A do CP) tem a pena reduzida de 1/3 a 2/3 se:","opcoes":["O agente for primário e não integrar organização criminosa","A vítima for maior de idade","O crime for transnacional","A vítima for criança"],"explicacao":"Art. 149-A, § 2º, do CP."},{"id":7720,"materia":"leg","nivel":4,"enunciado":"Pela Lei 13.260/2016, o terrorismo é praticado por razões de:","opcoes":["Xenofobia, discriminação ou preconceito de raça, cor, etnia e religião","Qualquer motivo político, inclusive manifestação pacífica","Interesse econômico simples","Disputa entre vizinhos"],"explicacao":"Art. 2º. Manifestações políticas e movimentos sociais com fins legítimos ficam de fora (§ 2º)."},{"id":7721,"materia":"ppen","nivel":0,"enunciado":"Na prisão em flagrante, o preso deve receber, em até 24 horas, a:","opcoes":["Nota de culpa","Sentença","Denúncia","Carta precatória"],"explicacao":"Art. 306, § 2º, do CPP."},{"id":7722,"materia":"ppen","nivel":0,"enunciado":"Qualquer pessoa do povo pode prender quem esteja em flagrante delito?","opcoes":["Sim, é uma faculdade","Não, só policiais podem","Só se for parente da vítima","Só com autorização do juiz"],"explicacao":"Art. 301: qualquer do povo poderá; as autoridades policiais e seus agentes deverão."},{"id":7723,"materia":"ppen","nivel":0,"enunciado":"Ao final do inquérito, o delegado elabora o:","opcoes":["Relatório","Acórdão","Parecer","Mandado"],"explicacao":"Art. 10, § 1º, do CPP."},{"id":7724,"materia":"ppen","nivel":0,"enunciado":"O interrogatório do réu é, entre outras coisas, um meio de:","opcoes":["Defesa","Acusação obrigatória","Prova pericial","Recurso"],"explicacao":"O réu tem direito ao silêncio, que não pode prejudicá-lo."},{"id":7725,"materia":"ppen","nivel":0,"enunciado":"Quem expede o mandado de prisão preventiva?","opcoes":["O juiz","O delegado","O promotor","O escrivão"],"explicacao":"Prisão por ordem escrita e fundamentada da autoridade judiciária."},{"id":7726,"materia":"ppen","nivel":0,"enunciado":"A testemunha que, intimada, não comparece sem justificativa pode ser:","opcoes":["Conduzida coercitivamente","Presa preventivamente","Condenada por falso testemunho","Dispensada sem consequência"],"explicacao":"Art. 218 do CPP."},{"id":7727,"materia":"ppen","nivel":0,"enunciado":"A carta precatória é usada para:","opcoes":["Pedir a juiz de outra comarca que pratique um ato processual","Recorrer de sentença","Prender o réu","Arquivar o inquérito"],"explicacao":""},{"id":7728,"materia":"ppen","nivel":1,"enunciado":"O flagrante impróprio (quase flagrante) ocorre quando o agente:","opcoes":["É perseguido logo após o crime, em situação que faça presumir ser o autor","Está cometendo o crime","É encontrado dias depois com documentos","É preso por mandado"],"explicacao":"Art. 302, III, do CPP."},{"id":7729,"materia":"ppen","nivel":1,"enunciado":"A representação do ofendido, na ação pública condicionada, exige forma rígida?","opcoes":["Não, basta a manifestação inequívoca de vontade","Sim, só por escritura pública","Sim, só por advogado","Sim, só em juízo"],"explicacao":"Jurisprudência do STF e do STJ."},{"id":7730,"materia":"ppen","nivel":1,"enunciado":"A perempção na ação penal privada ocorre, por exemplo, quando o querelante:","opcoes":["Deixa de promover o andamento do processo por 30 dias seguidos","Oferece a queixa no prazo","Pede a condenação nas alegações finais","Comparece às audiências"],"explicacao":"Art. 60 do CPP."},{"id":7731,"materia":"ppen","nivel":2,"enunciado":"A prisão domiciliar no lugar da preventiva pode ser concedida, entre outros casos, à:","opcoes":["Gestante ou mulher com filho de até 12 anos incompletos","Qualquer pessoa primária","Pessoa com mais de 60 anos","Pessoa com emprego fixo"],"explicacao":"Art. 318 do CPP; o idoso só a partir de 80 anos."},{"id":7732,"materia":"ppen","nivel":2,"enunciado":"Medidas cautelares diversas da prisão incluem:","opcoes":["Comparecimento periódico em juízo, proibição de frequentar lugares e monitoração eletrônica","Pena de multa definitiva","Perda do cargo como pena","Interdição perpétua"],"explicacao":"Art. 319 do CPP."},{"id":7733,"materia":"ppen","nivel":2,"enunciado":"A prisão temporária comum tem prazo de:","opcoes":["5 dias, prorrogável por mais 5 em caso de extrema e comprovada necessidade","10 dias, improrrogáveis","30 dias","15 dias"],"explicacao":"Art. 2º da Lei 7.960/1989."},{"id":7734,"materia":"ppen","nivel":2,"enunciado":"Quem decreta a prisão temporária?","opcoes":["O juiz, mediante representação do delegado ou requerimento do MP","O delegado","O promotor","O secretário de segurança"],"explicacao":"Art. 2º da Lei 7.960/1989; não pode ser decretada de ofício."},{"id":7735,"materia":"ppen","nivel":2,"enunciado":"Ao receber o auto de prisão em flagrante, o juiz deve fundamentadamente:","opcoes":["Relaxar a prisão ilegal, converter em preventiva ou conceder liberdade provisória","Sempre manter a prisão","Sempre soltar","Mandar o caso para o júri"],"explicacao":"Art. 310 do CPP."},{"id":7736,"materia":"ppen","nivel":3,"enunciado":"A prisão preventiva exige prova da existência do crime, indício suficiente de autoria e:","opcoes":["Perigo gerado pelo estado de liberdade do imputado","Confissão do réu","Reincidência obrigatória","Pena máxima superior a 8 anos"],"explicacao":"Art. 312 do CPP."},{"id":7737,"materia":"ppen","nivel":3,"enunciado":"Em regra, a prisão preventiva é admitida nos crimes dolosos com pena máxima:","opcoes":["Superior a 4 anos","Superior a 2 anos","Superior a 8 anos","De qualquer tamanho"],"explicacao":"Art. 313, I, do CPP, com outras hipóteses (reincidência, violência doméstica)."},{"id":7738,"materia":"ppen","nivel":3,"enunciado":"A competência por prerrogativa de função dos deputados federais no STF, segundo o STF, alcança:","opcoes":["Crimes cometidos no cargo e em razão das funções, mantida após a saída do cargo","Qualquer crime, inclusive anterior ao mandato","Apenas crimes eleitorais","Apenas crimes cometidos após o mandato"],"explicacao":"STF, AP 937 e HC 232.627 (2025)."},{"id":7739,"materia":"ppen","nivel":3,"enunciado":"No Júri, os jurados respondem aos quesitos por meio de:","opcoes":["Cédulas com as palavras sim e não, em votação sigilosa","Discurso oral público","Votação aberta com braço levantado","Escrita de voto fundamentado"],"explicacao":"Arts. 485 e 486 do CPP."},{"id":7740,"materia":"ppen","nivel":3,"enunciado":"No Júri, a votação é encerrada quando:","opcoes":["Houver mais de 3 votos no mesmo sentido","Todos os 7 votarem","Houver empate","O juiz decidir"],"explicacao":"Art. 483, §§ 1º e 2º, do CPP: preserva o sigilo."},{"id":7741,"materia":"ppen","nivel":3,"enunciado":"Quem pode ser jurado?","opcoes":["Cidadão maior de 18 anos de notória idoneidade","Apenas bacharéis em direito","Somente servidores públicos","Qualquer pessoa, inclusive estrangeira"],"explicacao":"Art. 436 do CPP."},{"id":7742,"materia":"ppen","nivel":3,"enunciado":"Contra a decisão de impronúncia ou de absolvição sumária cabe:","opcoes":["Apelação","Recurso em sentido estrito","Carta testemunhável","Agravo"],"explicacao":"Art. 416 do CPP."},{"id":7743,"materia":"ppen","nivel":4,"enunciado":"O recurso em sentido estrito tem prazo de interposição de:","opcoes":["5 dias","15 dias","10 dias","3 dias"],"explicacao":"Art. 586 do CPP."},{"id":7744,"materia":"ppen","nivel":4,"enunciado":"Os embargos de declaração no processo penal devem ser opostos em:","opcoes":["2 dias","5 dias","10 dias","15 dias"],"explicacao":"Art. 619 do CPP. No Juizado: 5 dias."},{"id":7745,"materia":"ppen","nivel":4,"enunciado":"Segundo a Súmula 523 do STF, no processo penal:","opcoes":["A falta de defesa constitui nulidade absoluta; a deficiência só anula se houver prova de prejuízo","Qualquer deficiência da defesa anula o processo","A falta de defesa nunca anula","A defesa é facultativa"],"explicacao":"Súmula 523 do STF."},{"id":7746,"materia":"ppen","nivel":4,"enunciado":"A emendatio libelli ocorre quando:","opcoes":["O juiz dá ao fato definição jurídica diversa da denúncia, sem modificar a descrição do fato","Surge prova de fato novo não descrito na denúncia","O MP desiste da ação","O réu muda de advogado"],"explicacao":"Art. 383 do CPP. A mutatio libelli (art. 384) exige aditamento."},{"id":7747,"materia":"ppen","nivel":4,"enunciado":"Na mutatio libelli, encerrada a instrução e surgindo elemento não contido na denúncia, o MP deverá:","opcoes":["Aditar a denúncia em 5 dias","Arquivar o processo","Oferecer nova denúncia em outro juízo","Pedir a absolvição"],"explicacao":"Art. 384 do CPP."},{"id":7748,"materia":"ppen","nivel":4,"enunciado":"Segundo o STF, a gravação clandestina feita por um dos interlocutores, sem conhecimento do outro, é:","opcoes":["Lícita como prova, em regra, se não houver causa legal de sigilo","Sempre ilícita","Lícita só com ordem judicial","Interceptação ilegal"],"explicacao":"STF, RE 583.937 (Tema 237)."},{"id":7749,"materia":"ppen","nivel":4,"enunciado":"A captação ambiental de sinais para investigação, após o Pacote Anticrime, exige:","opcoes":["Autorização judicial e crimes com pena máxima superior a 4 anos","Apenas ordem do delegado","Somente requerimento da vítima","Nenhuma autorização"],"explicacao":"Art. 8º-A da Lei 9.296/1996."},{"id":7750,"materia":"ppen","nivel":4,"enunciado":"No acordo de não persecução penal, a homologação é feita:","opcoes":["Pelo juiz, em audiência na qual verifica a voluntariedade, ouvindo o investigado com seu defensor","Pelo delegado","Pela vítima","Pelo tribunal"],"explicacao":"Art. 28-A, § 4º, do CPP."},{"id":7751,"materia":"ppen","nivel":4,"enunciado":"O ANPP não se aplica, entre outros casos, aos crimes:","opcoes":["Praticados no âmbito de violência doméstica ou familiar contra a mulher","Patrimoniais sem violência","De trânsito culposos","Contra a ordem tributária"],"explicacao":"Art. 28-A, § 2º, IV, do CPP."},{"id":7752,"materia":"ppen","nivel":4,"enunciado":"A competência para julgar crime cometido a bordo de navio ou aeronave é da:","opcoes":["Justiça Federal, ressalvada a competência da Justiça Militar","Justiça Estadual sempre","Justiça do Trabalho","Justiça Eleitoral"],"explicacao":"Art. 109, IX, da CF."},{"id":7753,"materia":"ppen","nivel":4,"enunciado":"Os crimes contra a organização do trabalho, quando atingem direitos coletivos dos trabalhadores, são julgados pela:","opcoes":["Justiça Federal","Justiça do Trabalho","Justiça Estadual","Justiça Militar"],"explicacao":"Art. 109, VI, da CF e jurisprudência do STF."},{"id":7754,"materia":"const","nivel":0,"enunciado":"A República Federativa do Brasil é formada pela união indissolúvel dos:","opcoes":["Estados, municípios e Distrito Federal","Estados e territórios apenas","Municípios e regiões metropolitanas","Poderes Executivo e Legislativo"],"explicacao":"Art. 1º da CF."},{"id":7755,"materia":"const","nivel":0,"enunciado":"Todo o poder emana do:","opcoes":["Povo","Presidente da República","Congresso Nacional","Supremo Tribunal Federal"],"explicacao":"Art. 1º, parágrafo único, da CF."},{"id":7756,"materia":"const","nivel":0,"enunciado":"Quais são os Poderes da União?","opcoes":["Legislativo, Executivo e Judiciário","Executivo, Militar e Judiciário","Legislativo, Moderador e Executivo","Judiciário, Ministério Público e Polícia"],"explicacao":"Art. 2º da CF: independentes e harmônicos entre si."},{"id":7757,"materia":"const","nivel":0,"enunciado":"Pela Constituição, homens e mulheres são:","opcoes":["Iguais em direitos e obrigações","Diferentes em direitos políticos","Iguais apenas no trabalho","Desiguais perante a lei"],"explicacao":"Art. 5º, I."},{"id":7758,"materia":"const","nivel":0,"enunciado":"A Constituição assegura o direito de reunião pacífica, sem armas, em locais abertos ao público:","opcoes":["Independentemente de autorização, com prévio aviso à autoridade","Somente com autorização da polícia","Apenas aos domingos","Somente para partidos políticos"],"explicacao":"Art. 5º, XVI."},{"id":7759,"materia":"const","nivel":0,"enunciado":"Pela Constituição, é livre o exercício de qualquer trabalho, ofício ou profissão:","opcoes":["Atendidas as qualificações profissionais que a lei estabelecer","Sem nenhuma restrição","Apenas com autorização do sindicato","Apenas para brasileiros natos"],"explicacao":"Art. 5º, XIII."},{"id":7760,"materia":"const","nivel":0,"enunciado":"O voto, no Brasil, é:","opcoes":["Direto, secreto, universal e periódico","Indireto e aberto","Facultativo para todos","Censitário"],"explicacao":"Art. 14 e art. 60, § 4º, II."},{"id":7761,"materia":"const","nivel":1,"enunciado":"A ação popular pode ser proposta para anular ato lesivo:","opcoes":["Ao patrimônio público, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural","A interesses de empresas privadas","Apenas a direitos trabalhistas","Somente a direitos de crianças"],"explicacao":"Art. 5º, LXXIII."},{"id":7762,"materia":"const","nivel":1,"enunciado":"O autor da ação popular, salvo comprovada má-fé, fica isento de:","opcoes":["Custas judiciais e do ônus da sucumbência","Comparecer ao processo","Provar o alegado","Pagar impostos"],"explicacao":"Art. 5º, LXXIII."},{"id":7763,"materia":"const","nivel":2,"enunciado":"A lei não excluirá da apreciação do Poder Judiciário:","opcoes":["Lesão ou ameaça a direito","Apenas lesões consumadas","Só questões criminais","Decisões administrativas em nenhum caso"],"explicacao":"Inafastabilidade da jurisdição: art. 5º, XXXV."},{"id":7764,"materia":"const","nivel":2,"enunciado":"A Constituição garante aos litigantes e acusados em geral:","opcoes":["O contraditório e a ampla defesa, com os meios e recursos a ela inerentes","Apenas o direito de recorrer","Defesa somente no processo judicial","Julgamento sigiloso"],"explicacao":"Art. 5º, LV."},{"id":7765,"materia":"const","nivel":2,"enunciado":"São inadmissíveis no processo as provas obtidas por:","opcoes":["Meios ilícitos","Testemunhas","Perícia","Documentos públicos"],"explicacao":"Art. 5º, LVI."},{"id":7766,"materia":"const","nivel":2,"enunciado":"O preso será informado de seus direitos, entre os quais o de:","opcoes":["Permanecer calado, assegurada a assistência da família e de advogado","Escolher o juiz","Ser solto em 24 horas","Não ser identificado"],"explicacao":"Art. 5º, LXIII."},{"id":7767,"materia":"const","nivel":2,"enunciado":"A Constituição prevê como penas, entre outras:","opcoes":["Privação ou restrição da liberdade, perda de bens, multa, prestação social alternativa e suspensão ou interdição de direitos","Banimento e trabalhos forçados","Pena de morte em tempo de paz","Prisão perpétua"],"explicacao":"Art. 5º, XLVI."},{"id":7768,"materia":"const","nivel":3,"enunciado":"A Constituição considera crimes inafiançáveis e insuscetíveis de graça ou anistia:","opcoes":["Tortura, tráfico de drogas, terrorismo e crimes hediondos","Racismo e ação de grupos armados","Todos os crimes contra a vida","Crimes contra o patrimônio"],"explicacao":"Art. 5º, XLIII. Racismo e ação de grupos armados são inafiançáveis e imprescritíveis."},{"id":7769,"materia":"const","nivel":3,"enunciado":"A ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático é crime:","opcoes":["Inafiançável e imprescritível","Afiançável","Prescritível em 20 anos","De menor potencial ofensivo"],"explicacao":"Art. 5º, XLIV."},{"id":7770,"materia":"const","nivel":3,"enunciado":"A Polícia Federal tem, entre suas funções:","opcoes":["Exercer com exclusividade as funções de polícia judiciária da União e prevenir e reprimir o tráfico ilícito de entorpecentes","Fazer o policiamento ostensivo das cidades","Patrulhar as rodovias estaduais","Julgar crimes federais"],"explicacao":"Art. 144, § 1º."},{"id":7771,"materia":"const","nivel":3,"enunciado":"Os municípios podem constituir guardas municipais destinadas à:","opcoes":["Proteção de seus bens, serviços e instalações, conforme a lei","Investigação de homicídios","Defesa das fronteiras","Execução penal"],"explicacao":"Art. 144, § 8º."},{"id":7772,"materia":"const","nivel":3,"enunciado":"A segurança viária, exercida para a preservação da ordem pública e da incolumidade das pessoas nas vias públicas, compreende:","opcoes":["A educação, engenharia e fiscalização de trânsito","Apenas a aplicação de multas","Somente a construção de estradas","A investigação de crimes de trânsito pela PM"],"explicacao":"Art. 144, § 10 (EC 82/2014)."},{"id":7773,"materia":"const","nivel":3,"enunciado":"Os servidores policiais são remunerados, nos termos da Constituição, na forma de:","opcoes":["Subsídio","Gratificação variável apenas","Salário regido pela CLT","Comissão por produtividade"],"explicacao":"Art. 144, § 9º, c/c art. 39, § 4º."},{"id":7774,"materia":"const","nivel":3,"enunciado":"Nos crimes de responsabilidade, o Presidente da República é julgado pelo:","opcoes":["Senado Federal, após admissão da acusação por 2/3 da Câmara","STF","STJ","Câmara dos Deputados"],"explicacao":"Arts. 51, I, 52, I, e 86 da CF."},{"id":7775,"materia":"const","nivel":4,"enunciado":"Nos crimes comuns, o Presidente da República é julgado pelo:","opcoes":["STF, após admissão da acusação por 2/3 da Câmara","Senado Federal","STJ","Tribunal do Júri"],"explicacao":"Art. 86 da CF."},{"id":7776,"materia":"const","nivel":4,"enunciado":"Os prefeitos, nos crimes comuns de competência da Justiça Estadual, são julgados pelo:","opcoes":["Tribunal de Justiça","Juiz de primeiro grau","STJ","Câmara de Vereadores"],"explicacao":"Art. 29, X, da CF."},{"id":7777,"materia":"const","nivel":4,"enunciado":"Os deputados e senadores, desde a expedição do diploma, não podem ser presos, salvo:","opcoes":["Em flagrante de crime inafiançável","Por ordem do delegado","Por qualquer crime","Por decisão do presidente da Casa"],"explicacao":"Art. 53, § 2º, da CF."},{"id":7778,"materia":"const","nivel":4,"enunciado":"A perda da nacionalidade do brasileiro pode ocorrer, entre outros casos, quando:","opcoes":["Tiver cancelada sua naturalização por sentença judicial em virtude de fraude ou atentado contra a ordem constitucional","Mudar de estado","Casar com estrangeiro","Ficar mais de 1 ano no exterior"],"explicacao":"Art. 12, § 4º, I (EC 131/2023)."},{"id":7779,"materia":"const","nivel":4,"enunciado":"O brasileiro nato que adquire outra nacionalidade, após a EC 131/2023:","opcoes":["Não perde a nacionalidade brasileira, salvo se pedir expressamente","Perde automaticamente","Perde se morar fora mais de 5 anos","Perde se votar no exterior"],"explicacao":"Art. 12, § 4º, II, com redação da EC 131/2023."},{"id":7780,"materia":"const","nivel":4,"enunciado":"São condições de elegibilidade, entre outras:","opcoes":["Nacionalidade brasileira, pleno exercício dos direitos políticos, alistamento eleitoral, domicílio eleitoral, filiação partidária e idade mínima","Curso superior e renda mínima","Ser brasileiro nato para qualquer cargo","Não ter filhos"],"explicacao":"Art. 14, § 3º."},{"id":7781,"materia":"const","nivel":4,"enunciado":"São inelegíveis, segundo a Constituição:","opcoes":["Os inalistáveis e os analfabetos","Os maiores de 70 anos","Os servidores públicos","Os naturalizados para qualquer cargo"],"explicacao":"Art. 14, § 4º."},{"id":7782,"materia":"const","nivel":4,"enunciado":"O controle concentrado de constitucionalidade de lei federal em face da Constituição Federal é feito pelo:","opcoes":["STF","STJ","Senado","Qualquer juiz"],"explicacao":"Art. 102, I, a. O controle difuso pode ser feito por qualquer juiz."},{"id":7783,"materia":"const","nivel":4,"enunciado":"Pode propor ação direta de inconstitucionalidade, entre outros:","opcoes":["O Presidente da República, o PGR, o Conselho Federal da OAB e partido político com representação no Congresso","Qualquer cidadão","Qualquer vereador","Qualquer delegado"],"explicacao":"Art. 103 da CF."},{"id":7784,"materia":"adm","nivel":0,"enunciado":"Divulgar em site oficial os gastos de um órgão público atende ao princípio da:","opcoes":["Publicidade","Legalidade","Impessoalidade","Eficiência"],"explicacao":"Art. 37 da CF."},{"id":7785,"materia":"adm","nivel":0,"enunciado":"Proibir que a publicidade oficial traga o nome ou a foto do governante atende ao princípio da:","opcoes":["Impessoalidade","Eficiência","Legalidade","Publicidade"],"explicacao":"Art. 37, § 1º, da CF."},{"id":7786,"materia":"adm","nivel":0,"enunciado":"Fazer o serviço público com rapidez, qualidade e menor custo atende ao princípio da:","opcoes":["Eficiência","Moralidade","Impessoalidade","Publicidade"],"explicacao":"Incluído pela EC 19/1998."},{"id":7787,"materia":"adm","nivel":0,"enunciado":"Nomear parentes para cargos em comissão sem qualificação, por favorecimento, viola o princípio da:","opcoes":["Moralidade e impessoalidade (nepotismo)","Eficiência apenas","Publicidade","Legalidade estrita apenas"],"explicacao":"Súmula Vinculante 13."},{"id":7788,"materia":"adm","nivel":0,"enunciado":"A administração indireta é composta por:","opcoes":["Autarquias, fundações públicas, empresas públicas e sociedades de economia mista","Ministérios e secretarias","Câmaras municipais","Partidos políticos"],"explicacao":"Decreto-Lei 200/1967."},{"id":7789,"materia":"adm","nivel":0,"enunciado":"O INSS e as universidades federais são exemplos de:","opcoes":["Autarquias","Empresas públicas","Sociedades de economia mista","Órgãos da administração direta"],"explicacao":""},{"id":7790,"materia":"adm","nivel":0,"enunciado":"A Petrobras e o Banco do Brasil são:","opcoes":["Sociedades de economia mista","Autarquias","Fundações públicas","Empresas públicas"],"explicacao":"Capital público e privado, com controle estatal."},{"id":7791,"materia":"adm","nivel":1,"enunciado":"A Caixa Econômica Federal e os Correios são:","opcoes":["Empresas públicas","Sociedades de economia mista","Autarquias","Órgãos públicos"],"explicacao":"Capital integralmente público."},{"id":7792,"materia":"adm","nivel":1,"enunciado":"O servidor que exerce o poder de polícia ao fiscalizar e multar deve agir com:","opcoes":["Proporcionalidade, sem excesso","Total liberdade, sem limites","Interesse pessoal","Sigilo absoluto"],"explicacao":"Abuso de poder torna o ato ilegal."},{"id":7793,"materia":"adm","nivel":1,"enunciado":"A Lei 9.784/1999 regula o:","opcoes":["Processo administrativo no âmbito federal","Regime dos servidores federais","Licitações","Improbidade administrativa"],"explicacao":""},{"id":7794,"materia":"adm","nivel":1,"enunciado":"A delegação de competência administrativa NÃO é permitida para:","opcoes":["Editar atos normativos, decidir recursos administrativos e matérias de competência exclusiva","Atos de rotina","Assinar ofícios","Despachos simples"],"explicacao":"Art. 13 da Lei 9.784/1999."},{"id":7795,"materia":"adm","nivel":2,"enunciado":"A avocação de competência é:","opcoes":["O superior chamar para si, temporariamente, competência do subordinado, em caráter excepcional","O subordinado decidir no lugar do chefe","A transferência definitiva de competência","A anulação de um ato"],"explicacao":"Art. 15 da Lei 9.784/1999."},{"id":7796,"materia":"adm","nivel":2,"enunciado":"O prazo para interpor recurso administrativo na Lei 9.784 é de:","opcoes":["10 dias","15 dias","5 dias","30 dias"],"explicacao":"Art. 59 da Lei 9.784/1999."},{"id":7797,"materia":"adm","nivel":2,"enunciado":"Pela Lei 8.112, o estágio probatório tem duração de:","opcoes":["3 anos, segundo a CF e o entendimento do STF e do STJ","2 anos","1 ano","5 anos"],"explicacao":"Art. 41 da CF (EC 19/1998)."},{"id":7798,"materia":"adm","nivel":2,"enunciado":"Pela Lei 8.112, a advertência é aplicada por escrito em casos como:","opcoes":["Ausentar-se do serviço sem autorização do chefe, durante o expediente","Abandono de cargo","Corrupção","Improbidade"],"explicacao":"Arts. 117, I, e 129."},{"id":7799,"materia":"adm","nivel":3,"enunciado":"Pela Lei 8.112, a demissão é aplicada, entre outros casos, por:","opcoes":["Valer-se do cargo para lograr proveito pessoal em detrimento da dignidade da função","Atraso de 15 minutos","Faltar uma vez com justificativa","Discordar do chefe"],"explicacao":"Arts. 117, IX, e 132, XIII."},{"id":7800,"materia":"adm","nivel":3,"enunciado":"A sindicância, na Lei 8.112, pode resultar em:","opcoes":["Arquivamento, advertência ou suspensão de até 30 dias, ou instauração de PAD","Demissão direta","Cassação de aposentadoria","Prisão do servidor"],"explicacao":"Art. 145 da Lei 8.112/1990."},{"id":7801,"materia":"adm","nivel":3,"enunciado":"O prazo para conclusão do PAD é de:","opcoes":["60 dias, prorrogável por igual prazo","30 dias, improrrogável","90 dias","120 dias"],"explicacao":"Art. 152 da Lei 8.112/1990."},{"id":7802,"materia":"adm","nivel":3,"enunciado":"Na responsabilidade civil do Estado, são excludentes ou atenuantes:","opcoes":["Culpa exclusiva da vítima, caso fortuito, força maior e culpa de terceiro","Apenas a culpa do servidor","A pobreza da vítima","O horário do fato"],"explicacao":"Teoria do risco administrativo."},{"id":7803,"materia":"adm","nivel":4,"enunciado":"O Brasil adota, em regra, para a responsabilidade do Estado, a teoria do:","opcoes":["Risco administrativo","Risco integral","Culpa administrativa exclusiva","Irresponsabilidade"],"explicacao":"O risco integral é admitido em casos excepcionais (dano nuclear, ambiental)."},{"id":7804,"materia":"adm","nivel":4,"enunciado":"A Súmula Vinculante 13 veda a nomeação para cargo em comissão de:","opcoes":["Cônjuge, companheiro ou parente até o 3º grau da autoridade nomeante ou de servidor investido em cargo de direção","Qualquer amigo","Parentes até o 5º grau","Apenas filhos"],"explicacao":"Inclui o nepotismo cruzado."},{"id":7805,"materia":"adm","nivel":4,"enunciado":"Pela Lei de Improbidade, após a Lei 14.230/2021, os atos que atentam contra os princípios da administração estão em rol:","opcoes":["Taxativo","Exemplificativo","Aberto a qualquer conduta","Revogado"],"explicacao":"Art. 11 da Lei 8.429/1992."},{"id":7806,"materia":"adm","nivel":4,"enunciado":"A Lei 12.846/2013 (Lei Anticorrupção) responsabiliza:","opcoes":["Objetivamente pessoas jurídicas por atos contra a administração pública","Apenas servidores públicos","Somente pessoas físicas","Partidos políticos, exclusivamente"],"explicacao":"Responsabilidade objetiva, civil e administrativa."},{"id":7807,"materia":"adm","nivel":4,"enunciado":"Na Lei Anticorrupção, a multa administrativa pode chegar a:","opcoes":["20% do faturamento bruto do último exercício","50% do patrimônio","10 vezes o lucro","5% do capital social"],"explicacao":"Art. 6º, I, da Lei 12.846/2013."},{"id":7808,"materia":"adm","nivel":4,"enunciado":"O poder normativo da administração não permite:","opcoes":["Inovar no ordenamento criando obrigações não previstas em lei, salvo decreto autônomo nas hipóteses do art. 84, VI","Editar decretos de execução","Expedir instruções","Regulamentar leis"],"explicacao":"Art. 84, IV e VI, da CF."},{"id":7809,"materia":"adm","nivel":4,"enunciado":"A Lei de Licitações em vigor é a:","opcoes":["Lei 14.133/2021","Lei 8.666/1993","Lei 10.520/2002","Lei 12.462/2011"],"explicacao":"Substituiu as anteriores, revogadas em 2023 e 2024."},{"id":7810,"materia":"port","nivel":0,"enunciado":"Complete: “O perito chegou ___ conclusão de que houve incêndio criminoso.”","opcoes":["à","a","há","ah"],"explicacao":"Chegar a + a conclusão = à."},{"id":7811,"materia":"port","nivel":0,"enunciado":"Complete: “Os documentos estão ___ disposição do juiz.”","opcoes":["à","a","há","as"],"explicacao":"Locução feminina: à disposição."},{"id":7812,"materia":"port","nivel":0,"enunciado":"Complete: “Ele estuda ___ passar no concurso.”","opcoes":["para","pra que","por","porque"],"explicacao":"Indica finalidade."},{"id":7813,"materia":"port","nivel":0,"enunciado":"Qual frase está correta quanto ao uso de “onde” e “aonde”?","opcoes":["Aonde você vai com a viatura?","Onde você vai com a viatura?","Aonde fica a delegacia?","Aonde você mora?"],"explicacao":"Aonde com verbos de movimento (ir a); onde indica lugar fixo."},{"id":7814,"materia":"port","nivel":0,"enunciado":"Qual a forma correta?","opcoes":["Ele tem mais de vinte anos de serviço.","Ele tem mais de vinte anos de serviços prestado.","Ele têm mais de vinte anos de serviço.","Eles tem mais de vinte anos de serviço."],"explicacao":"Ele tem; eles têm."},{"id":7815,"materia":"port","nivel":0,"enunciado":"Qual palavra está acentuada corretamente?","opcoes":["Delegacia","Delegacía","Délegacia","Delegácia"],"explicacao":"De-le-ga-ci-a: paroxítona terminada em -a, sem acento."},{"id":7816,"materia":"port","nivel":0,"enunciado":"Qual frase usa corretamente “mas” ou “mais”?","opcoes":["Ele correu, mas não alcançou o suspeito.","Ele correu, mais não alcançou o suspeito.","Ele quer mas tempo para estudar.","Mas de dez agentes participaram."],"explicacao":"Mas: oposição. Mais: intensidade ou quantidade."},{"id":7817,"materia":"port","nivel":0,"enunciado":"Qual frase usa corretamente “a fim” ou “afim”?","opcoes":["Fiz o curso a fim de passar na prova.","Fiz o curso afim de passar na prova.","Ele é a fim ao cargo.","Os cargos são a fins."],"explicacao":"A fim de: finalidade. Afim: semelhante, parente por afinidade."},{"id":7818,"materia":"port","nivel":0,"enunciado":"Qual frase está correta quanto ao uso de “senão” e “se não”?","opcoes":["Estude, senão vai reprovar.","Estude, se não vai reprovar.","Senão chover, sairemos.","Não fez nada se não reclamar."],"explicacao":"Senão = caso contrário. Se não = caso não."},{"id":7819,"materia":"port","nivel":1,"enunciado":"Qual frase está correta?","opcoes":["Houve muitas prisões ontem.","Houveram muitas prisões ontem.","Ouveram muitas prisões ontem.","Houve-se muitas prisões ontem."],"explicacao":"Haver = existir, ocorrer: impessoal."},{"id":7820,"materia":"port","nivel":1,"enunciado":"Qual frase está correta quanto à concordância?","opcoes":["Mais de um suspeito fugiu.","Mais de um suspeito fugiram.","Mais de um suspeitos fugiu.","Mais de um suspeito fugiram-se."],"explicacao":"“Mais de um” leva o verbo ao singular."},{"id":7821,"materia":"port","nivel":1,"enunciado":"Na frase “O delegado, homem experiente, conduziu o caso”, o termo “homem experiente” é:","opcoes":["Aposto","Vocativo","Sujeito","Objeto direto"],"explicacao":"Explica o termo anterior e fica entre vírgulas."},{"id":7822,"materia":"port","nivel":1,"enunciado":"Na frase “Agente, aproxime-se!”, o termo “Agente” é:","opcoes":["Vocativo","Aposto","Sujeito","Objeto indireto"],"explicacao":"Chama o interlocutor e vem separado por vírgula."},{"id":7823,"materia":"port","nivel":2,"enunciado":"Em “O suspeito foi preso pelos agentes”, a voz verbal é:","opcoes":["Passiva analítica","Ativa","Reflexiva","Passiva sintética"],"explicacao":"Verbo ser + particípio + agente da passiva."},{"id":7824,"materia":"port","nivel":2,"enunciado":"Passando para a voz ativa “O laudo foi assinado pelo perito”, tem-se:","opcoes":["O perito assinou o laudo.","O laudo assinou o perito.","Assinou-se o laudo.","O perito foi assinado."],"explicacao":"O agente da passiva vira sujeito."},{"id":7825,"materia":"port","nivel":2,"enunciado":"A conjunção “porém” expressa ideia de:","opcoes":["Oposição (adversidade)","Conclusão","Causa","Adição"],"explicacao":"Equivale a mas, contudo, todavia."},{"id":7826,"materia":"port","nivel":3,"enunciado":"Qual frase está correta quanto à regência?","opcoes":["Obedeço às normas da corporação.","Obedeço as normas da corporação.","Obedeço com as normas da corporação.","Obedeço nas normas da corporação."],"explicacao":"Obedecer exige “a”: obedecer às normas."},{"id":7827,"materia":"port","nivel":3,"enunciado":"Qual frase está correta quanto à regência?","opcoes":["O policial chegou à cena do crime.","O policial chegou na cena do crime.","O policial chegou para a cena do crime.","O policial chegou em a cena do crime."],"explicacao":"Na norma-padrão, chegar a algum lugar."},{"id":7828,"materia":"port","nivel":3,"enunciado":"Qual frase está correta quanto à regência?","opcoes":["Esqueci o nome do suspeito.",